  'wf.my.changed.title': ['Your schedule changed', 'Változott a beosztásod', 'Tu horario ha cambiado', 'Lịch làm việc của bạn đã thay đổi', 'Таны хуваарь өөрчлөгдлөө', 'Qrafikiniz dəyişdi', 'Nagbago ang iskedyul mo', 'Ваш графік змінено', 'Ваш график изменён'],
